class Camera {
  public position: Vector3;
  public rotation: Quaternion;
  public fov: number;

  constructor(position: Vector3, rotation: Quaternion, fov: number) {
    this.position = position;
    this.rotation = rotation;
    this.fov = fov;
  }

  // Move the camera forward by a specified amount
  public moveForward(distance: number): void {
    this.position.z -= distance;
  }

  // Rotate the camera around its vertical axis by a specified angle
  public rotateVertical(angle: number): void {
    const quat = new Quaternion();
    quat.setFromAxisAngle(new Vector3(0, 1, 0), -angle);
    this.rotation.multiply(quat);
  }

  // Zoom the camera in or out by a specified amount
  public zoom(amount: number): void {
    this.fov += amount;
  }
}
```

