class Transaction {
  String coinName;
  DateTime datetime;
  int profitOrLoss;

  double get averageProfit => (profitOrLoss).toDouble() / datetime.difference(DateTime.now()).inDays;
  double get averageLoss => (profitOrLoss * -1).toDouble() / datetime.difference(DateTime.now()).inDays;

  Transaction({required this.coinName, required this.datetime, required this.profitOrLoss});
