List<Transaction> getTopCoinsByAverageProfit(List<Transaction> transactions) {
  transactions.sort((a, b) => (-a.averageProfit).compareTo(-b.averageProfit));
  return List.from(transactions.sublist(0, 3));
}

List<Transaction> getTopCoinsByAverageLoss(List<Transaction> transactions) {
  transactions.sort((a, b) => (a.averageLoss).compareTo(b.averageLoss));
  return List.from(transactions.sublist(0, 3));
}
```

