function reverseAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(' ');

  // Initialize two pointers at the beginning and end of the array
  let left = 0;
  let right = words.length - 1;

  // Swap adjectives (words between "a", "an", or "the" and another space)
  while (left <= right) {
    let isAdjective = false;

    // Move left pointer to find next adjective
    while (left <= right && !isAdjective) {
      const word = words[left];

      // Check for articles ("a", "an", or "the")
      const articles = ["a", "an", "the"];

      // If current word is not an article and the next word is also not an article, it's an adjective
      isAdjective = !articles.includes(word) && !articles.includes(words[left + 1]);

      left++;
    }

