function switchAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(" ");

  // Find the index of the first adjective (excluding "be")
  let firstAdjIndex = -1;
  for (let i = 0; i < words.length; i++) {
    if (words[i] === "be" || words[i].endsWith("en")) {
      continue;
    } else if (isAdjective(words[i])) {
      firstAdjIndex = i;
      break;
    }
  }

  // If no adjectives found, return original sentence
  if (firstAdjIndex === -1) {
    return sentence;
  }

  // Swap the positions of the first and last adjectives
  const firstAdj = words.splice(firstAdjIndex, 1)[0];
  const lastAdj = words.pop();

  // Insert the first adjective at the end of the sentence
  words.push(firstAdj);

  // Insert the last adjective before the noun
  const nounIndex = words.indexOf("are");
  if (nounIndex === -1) {
    nounIndex = words.lastIndexOf("in");
  }
  words.splice(nounIndex + 1, 0, lastAdj);

  // Join the words back into a sentence
  return words.join(" ");
}

