class BaseModel(models.Model):
    # Common fields for both tables go here
    created_at = models.DateTimeField(_("Created at"), auto_now_add=True)
    updated_at = models.DateTimeField(_("Updated at"), auto_now=True)

    class Meta:
        abstract = True

    @cached_property
    def __str__(self):
        return self.get_display_name()

    def get_display_name(self):
        """
        Returns a human-readable display name based on the current model
        """
        return self.__class__.__name__.lower().replace('model', '').capitalize()

class TableOne(BaseModel):
    # Unique columns for Table One go here
    column1 = models.IntegerField(_("Column 1"))

    class Meta:
        db_table = "table_one"

class TableTwo(BaseModel):
    # Unique columns for Table Two go here
    column2 = models.CharField(_("Column 2"), max_length=255)

    class Meta:
        db_table = "table_two"
```

