   $string = preg_replace('/[^a-zA-Z0-9-\s]/', '', $string); // Remove unwanted characters
   $string = trim(preg_replace('/[\s_-]+/', ' ', $string)); // Convert multiple spaces and hyphens to single space
   $string = preg_replace('/[_\s]+/', '-', $string); // Replace underscores and spaces with hyphens
   $string = preg_replace('/^-+|\s+-/', '', $string); // Trim leading/trailing hyphens and spaces
   $string = strtolower($string); // Convert to lowercase
   return $string;
}

