Here's an example of how you could create a generic REST service wrapper class in C# with authentication token handling:

First, let's define an interface `IRestService` that all services will implement:

```csharp
public interface IRestService
{
    string BaseUrl { get; }
    string AuthorizationToken { get; set; }
    Task<HttpResponseMessage> GetAsync(string uri);
    Task<HttpResponseMessage> PostAsync(string uri, HttpContent content);
}
```

This interface has two properties - `BaseUrl` and `AuthorizationToken`. The `BaseUrl` is the base URL for the REST service, while the `AuthorizationToken` is where the user's authentication token would be stored. Both properties are readable and writable to allow for customization at runtime.

The `GetAsync()` and `PostAsync()` methods return `Task<HttpResponseMessage>` and take a `string` URI and an optional `HttpContent`, respectively. These methods make HTTP requests using the `HttpClient` class from the .NET Framework System.Net.Http namespace.

Next, let's create our implementation of this interface, which we'll call `RestServiceWrapper`:

```csharp
public abstract class RestServiceWrapper : IRestService
{
    private readonly HttpClient _httpClient;

    protected RestServiceWrapper(string baseUrl)
    {
        _httpClient = new HttpClient();
        BaseUrl = baseUrl;
    }

    public string BaseUrl { get; }

    public string AuthorizationToken { get; set; }

    protected async Task<HttpResponseMessage> SendRequestAsync(HttpMethod method, string uri, HttpContent content)
    {
        var requestUri = $"{BaseUrl}{uri}";
        var request = new HttpRequestMessage(method, requestUri)
        {
            Content = content
        };

        if (!string.IsNullOrWhiteSpace(AuthorizationToken))
        {
            request.Headers.Add("Authorization", "Bearer " + AuthorizationToken);
        }

        var response = await _httpClient.SendAsync(request);
        response.EnsureSuccessStatusCode();

        return response;
    }

Here's an outline of how you could create a generic REST service wrapper class with authentication token handling in C#:

1. Define the interface for the REST service:

```csharp
public interface IRestService
{
    Task<HttpResponseMessage> GetAsync(string endpoint, Dictionary<string, string> queryParameters = null);
    Task<HttpResponseMessage> PostAsync(string endpoint, object data, Dictionary<string, string> headers = null);
}
```

2. Create the base class for the REST service wrapper:

```csharp
public abstract class RestServiceWrapperBase : IDisposable
{
    private HttpClient _httpClient;
    private string _baseUrl;
    private string _authToken;

    protected RestServiceWrapperBase(string baseUrl, string authToken)
    {
        _baseUrl = baseUrl;
        _authToken = authToken;
        _httpClient = new HttpClient();
        _httpClient.BaseAddress = new Uri(_baseUrl);
        _httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _authToken);
    }

    protected virtual Task<HttpResponseMessage> MakeHttpRequest(HttpMethod httpMethod, string endpoint, Dictionary<string, string> queryParameters = null, Dictionary<string, string> headers = null, object data = null)
    {
        HttpRequestMessage request = new HttpRequestMessage(httpMethod, endpoint);
        if (queryParameters != null)
        {
            request.RequestUri = new UriBuilder(endpoint).Query = QueryHelpers.AddQueryString(request.RequestUri.Query, queryParameters);
        }
        if (headers != null)
        {
            foreach (var header in headers)
            {
                request.Headers.Add(header.Key, header.Value);
            }
        }
        if (data != null)
        {
            request.Content = new StringContent(JsonConvert.SerializeObject(data), Encoding.UTF8, "application/json");
        }
        return _httpClient.SendAsync(request);
    }

    public void Dispose()
    {
        _httpClient.Dispose();
    }
}

