function findEntriesByKey(obj, keyPath) {
  let result = [];
  let parts = keyPath.split(".");

  for (let I = 0; I < obj.length; i++) {
    let entry = obj[i];

    // Check if entry is an object and has all required keys
    for (let j = 0; j < parts.length - 1; j++) {
      const part = parts[j];

      if (!entry || typeof entry[part] !== "object") {
        return result; // Stop searching if we reach the end of the array or the current entry doesn't have the next required key
      }

      entry = entry[part];
    }

    // Get the last required key and add the entry to the result list
    const lastPart = parts[parts.length - 1];
    const value = entry[lastPart];
    result.push({ [keyPath]: value });
  }

  return result;
}
```

