Here's a Javascript function that takes a string variable in dot notation and returns all entries in an object where the nested key-value pairs match:

```javascript
function findEntriesByKey(obj, keyPath) {
  let result = [];
  let pathParts = keyPath.split(".");

  // Traverse the object using the provided key path
  for (let I = 0; I < pathParts.length - 1; i++) {
    const currentObj = obj[pathParts[i]];

    if (typeof currentObj !== "object" || currentObj === null) {
      // If the next part of the path is not an object or null, stop searching
      break;
    }

    obj = currentObj;
  }

  // Add all entries from the last object to the result array
  for (const [key, value] of Object.entries(obj)) {
    result.push({ key, value });
  }

  // Return all entries found along the path
  return result;
}
```

