```js
function findObjectsByKey(array, key) {
  const regex = new RegExp(`[${key}]`, 'g');
  return array.filter((obj) => {
    let hasMatch = false;
    Object.keys(obj).some((prop) => {
      if (regex.test(prop)) {
        hasMatch = true;
        return obj[prop] === key || obj[prop].toString().includes(key);
      }
      return false;
    });
    return hasMatch;
  });
}

