```matlab
% Define parameters for simulation
populationSize = 100; % Number of individuals in population
generations = 1000; % Number of generations to simulate
mutationRate = 0.01; % Probability of mutating a gene
selectionPressure = 2; % Fitness difference between best and worst genotypes

% Initialize population with random genotypes
genes = rand(2, populationSize);
fitness = 0.5 * abs(genes(:, 1) - sin(pi / 2)) + 0.5 * abs(genes(:, 2) - cos(pi / 2)); % Fitness function based on distance from optimal values
survivors = sort(fitness, 'descend')(1:int(selectionPressure * populationSize)); % Select survivors based on fitness
offspring = crossOver(genes(sub2ind(size(genes), survivors, :)), genes(sub2ind(size(genes), survivors, :)), mutationRate); % Produce offspring through crossover and mutation
genes = [genes; offspring]; % Add offspring to population
genes = genes(1:populationSize, :); % Truncate population to desired size

% Print results after each generation
if rem(generations, 100) == 0
    fprintf('Generation %d\n', generations);
    avgFitness = mean(fitness);
    fprintf('Average fitness: %.4f\n', avgFitness);
end

function [children] = crossOver(parent1, parent2, mutationRate)
    % Perform single-point crossover with optional mutation
    crossoverPoint = floor(rand() * length(parent1(:, 1))) + 1;
