```typescript
import { ExecutionContext, Injectable } from '@nestjs/common';
import { Observable } from 'rxjs';

@Injectable()
export class DevelopmentOnlyMiddleware {
  constructor() {}

  public static use(): any {
    return this;
  }

  public static get IsDevelopmentEnvironment(): boolean {
    return process.env.NODE_ENV === 'development';
  }

  public async useFactory(context: ExecutionContext): Observable<any> {
    const request = context.switchToHttp().getRequest();

    if (DevelopmentOnlyMiddleware.IsDevelopmentEnvironment) {
      await request.resume();
      return super.useFactory(context);
    } else {
      return new Observable((observer) => {
        observer.next(false);
        observer.complete();
      });
    }
  }
}

// Example usage in your controller or service:
// @UseGuards(AuthGuard('jwt'))
// @DevelopmentOnly()
// export async myEndpoint() { ... }
//
// Or using the decorator as a factory:
// @Injectable()
// export class MyService {
//   constructor(private readonly developmentOnlyMiddleware: DevelopmentOnlyMiddleware) {}
//
//   @DevelopmentOnlyMiddleware.use()
//   public myMethod() { ... }
```

