```json
{
  "name": "Inject Script",
  "version": "1.0.0",
  "description": "Injects a script into web pages.",
  "permissions": ["activeTab"],
  "browser_action": {
    "default_title": "Inject Script"
  },
  "background": {
    "scripts": ["background.js"]
  },
  "manifest_version": 2
}
```

