Here are some suggestions to make the code more efficient:

1. Use memoization for components with stable inputs. This can significantly reduce the number of unnecessary re-renders and improve performance. For example, instead of creating a new `Prompt` component for each item in the `prompts` array, you could create a memoized version of it like this:

```jsx
const MemoizedPrompt = React.memo(({ prompt, name, index }) => {
  const { isOpen, onOpen, onClose } = useDisclosure();

  const handleDeleteClick = () => {
    void deletePrompt.mutateAsync({ id: prompts.data[index].id });
    onClose();
  };

  return (
    <ListItem
      key={prompt}
      p={2}
      borderBottomWidth="1px"
      borderBottomColor="gray.200"
      cursor="pointer"
      onClick={() => {
        setInputMessage(prompts.data[index].prompt);
      }}
    >
      <HStack flexWrap="wrap">
        <Text>{name}</Text>
        <Spacer />
        <IconButton
          aria-label="Delete"
          icon={<DeleteIcon />}
          size="sm"
          colorScheme="red"
          onClick={handleDeleteClick}
        />
      </HStack>
      <Text>{prompt}</Text>
      <Modal isOpen={isOpen} onClose={onClose}>
        ...
      </Modal>
    </ListItem>
  );
}, (prevProps, nextProps) => {
  return prevProps.prompt === nextProps.prompt && prevProps.name === nextProps.name;
});

return (
  <>
    ...
    {prompts.data?.map((p, index) => (
      <MemoizedPrompt
        key={p.prompt}
        index={index}
        name={p.name}
        prompt={p.prompt}
      />
    ))}
    ...
  </>
);
```

