      position: pos,
      size: randomSize(1, 5) * scale,
      color: randomColor(),
      ringSize: 0.2 * scale,
      ringColor: randomColor(),
      ringNoise: 0.3 * scale,
    };

    planets.push(planet);
  }

  return planets;
};

const calculateDistance = (a, b) => {
  const dx = a[0] - b[0];
  const dy = a[1] - b[1];
  const dz = a[2] - b[2];

  return Math.sqrt(dx * dx + dy * dy + dz * dz);
};
```

