```php
function createChatroom($userId) {
    global $conn;

    // Generate a random chatroom ID
    do {
        $chatroomId = bin2hex(random_bytes(16));
    } while (mysqli_num_rows(mysqli_query($conn, "SELECT * FROM chatrooms WHERE id = '$chatroomId'")) > 0);

    // Insert the new chatroom into the database
    mysqli_query($conn, "INSERT INTO chatrooms (id, user_id, chatting_id, created_at) VALUES ('$chatroomId', '$userId', '$userId', NOW())");

    // Return the newly created chatroom ID
    return $chatroomId;
}
```

