```swift
import Foundation

struct TimeSeriesDataPoint {
    var date: Date
    var value: Double
}

func calculateMA(_ dataPoints: [TimeSeriesDataPoint], windowSize: Int) -> Double {
    guard dataPoints.count >= windowSize else { return 0 }
    let sum = dataPoints[..<windowSize].reduce(0) { $0 + $1.value }
    let movingAverage = Double(dataPoints[windowSize - 1..<dataPoints.endIndex].prefix(windowSize - 1).reduce(sum) { $0 + ($1.date...$1.date+TimeInterval(1)).map { $0.value }.reduce(0) }) / Double(windowSize)
    return movingAverage
}

func calculateBollingerBands(_ dataPoints: [TimeSeriesDataPoint], windowSize: Int, standardDeviationPeriods: Int) -> (lowerBand: Double, upperBand: Double) {
    guard dataPoints.count >= windowSize * standardDeviationPeriods else { return (lowerBand: 0, upperBand: 0) }
    let rollingMean = dataPoints[..<windowSize].rollingStatistics(windowSize: windowSize, statistics: .mean) { $0.value }
    let rollingStdDev = dataPoints[..<windowSize].rollingStatistics(windowSize: windowSize * standardDeviationPeriods, statistics: .standardDeviation) { $0.value }
    let movingAverage = rollingMean[windowSize - 1]
    let standardDeviation = rollingStdDev[windowSize * standardDeviationPeriods - 1]
    let lowerBand = movingAverage - standardDeviation * standardDeviationPeriods
    let upperBand = movingAverage + standardDeviation * standardDeviationPeriods

