# Function to get the ACLs for all files and directories in the given path
function GetAcls($path) {
    $acls = Get-Acl -Path $path
    $results = @()
    foreach ($accessRule in $acls.Access) {
        $identity = $accessRule.IdentityReference
        $isInHistory = CheckSidInHistory($identity)
        $results += [PSCustomObject]@{
            Path = $path
            Identity = $identity
            IsInHistory = $isInHistory
            AccessRights = $accessRule.FileSystemRights -join ", "
            InheritedFrom = $accessRule.IsInherited
        }
    }
    return $results
}

